import{_ as i,C as a,o as d,c as o,j as t,a as n,E as s,a3 as l}from"./chunks/framework.BZKbe9n2.js";const k=JSON.parse('{"title":"Eine Sammlung importieren","description":"","frontmatter":{},"headers":[],"relativePath":"de/administration/import.md","filePath":"de/administration/import.md"}'),h={name:"de/administration/import.md"};function u(m,e,p,c,g,b){const r=a("Screenshot");return d(),o("div",null,[e[0]||(e[0]=t("h1",{id:"eine-sammlung-importieren",tabindex:"-1"},[n("Eine Sammlung importieren "),t("a",{class:"header-anchor",href:"#eine-sammlung-importieren","aria-label":'Permalink to "Eine Sammlung importieren"'},"​")],-1)),e[1]||(e[1]=t("p",null,[n("Administratoren importieren Ordner vom Server: "),t("strong",null,"Streaming › Ordner importieren"),n(". Wählbar sind nur Ordner unterhalb der Import-Ordner ("),t("code",null,"ANTHOLOGY_IMPORT_ROOTS"),n(", Vorgabe "),t("code",null,"/data/imports"),n(").")],-1)),s(r,{name:"import-dialog",alt:"Der Dialog zur Wahl eines Ordners für den Import"}),e[2]||(e[2]=l('<h2 id="so-lauft-ein-import" tabindex="-1">So läuft ein Import <a class="header-anchor" href="#so-lauft-ein-import" aria-label="Permalink to &quot;So läuft ein Import&quot;">​</a></h2><ol><li><strong>Ordner wählen</strong> und den Speichermodus, dann die Prüfung starten.</li><li>Anthology <strong>liest und analysiert</strong> jede Datei: Tags, technische Daten und einen akustischen Fingerabdruck. Noch wird nichts verschoben oder geändert.</li><li>Du erhältst einen <strong>Bericht</strong>: neue Titel, Duplikate von Titeln, die du schon hast, bessere oder schlechtere Kopien, Dateien, die eine Entscheidung brauchen.</li><li><strong>Bestätige</strong> den Bericht. Erst jetzt werden die Dateien abgelegt und die Einträge der Bibliothek angelegt. Danach erkennt Anthology die Aufnahmen und holt Cover.</li></ol><p>Du kannst die App schliessen, während ein Import läuft; er läuft auf dem Server weiter, und sein Fortschritt wird live angezeigt.</p><h2 id="speichermodi" tabindex="-1">Speichermodi <a class="header-anchor" href="#speichermodi" aria-label="Permalink to &quot;Speichermodi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modus</th><th>Was geschieht</th></tr></thead><tbody><tr><td>Verweisen</td><td>die Dateien bleiben, wo sie sind; Anthology verschiebt, benennt oder löscht sie nie</td></tr><tr><td>Verlinken</td><td>ein zweiter Name (Hardlink) oder ein Copy-on-Write-Klon (Reflink) in der Bibliothek – ohne zusätzlichen Platz; der Ordner muss auf demselben Dateisystem liegen wie die Bibliothek</td></tr><tr><td>Verschieben</td><td>die Dateien wandern in die Bibliothek (über Laufwerke hinweg: kopiert, per Prüfsumme geprüft, dann entfernt)</td></tr><tr><td>Kopieren</td><td>die Dateien werden kopiert und geprüft; die Quelle bleibt unverändert</td></tr></tbody></table><p>Der Import schlägt den sparsamsten Modus vor, den die Dateisysteme erlauben. Referenzierte Dateien lassen sich später unter Einstellungen in die verwaltete Ablage übernehmen.</p><h2 id="duplikate-und-qualitat" tabindex="-1">Duplikate und Qualität <a class="header-anchor" href="#duplikate-und-qualitat" aria-label="Permalink to &quot;Duplikate und Qualität&quot;">​</a></h2><p>Ist eine Datei eine Aufnahme, die du schon hast, vergleicht der Import die <strong>tatsächliche Qualität</strong> beider: Eine wirklich bessere Kopie kann das bestehende Original ersetzen, die schlechtere wird übersprungen. Unklare Fälle landen in der Prüfliste.</p>',8))])}const D=i(h,[["render",u]]);export{k as __pageData,D as default};
